// Authoring helper only. Generated HTML is served directly by GitHub Pages.
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { renderLab } from '../assets/statistics-labs.mjs';

const root = path.resolve(fileURLToPath(new URL('../', import.meta.url)));
const sources = {
  design: ['NCI: how clinical trials work', 'https://www.cancer.gov/research/participate/clinical-trials/how-trials-work'],
  e9: ['ICH E9: Statistical Principles for Clinical Trials (FDA)', 'https://www.fda.gov/regulatory-information/search-fda-guidance-documents/e9-statistical-principles-clinical-trials'],
  estimand: ['ICH E9(R1): estimands and sensitivity analysis, May 2021 (FDA, PDF)', 'https://www.fda.gov/media/148473/download'],
  endpoints: ['FDA: Clinical Trial Endpoints for the Approval of Cancer Drugs and Biologics', 'https://www.fda.gov/regulatory-information/search-fda-guidance-documents/clinical-trial-endpoints-approval-cancer-drugs-and-biologics'],
  wilson: ['NIST: confidence intervals for a proportion', 'https://www.itl.nist.gov/div898/handbook/prc/section2/prc241.htm'],
  asa: ['American Statistical Association: interpreting p-values (PDF)', 'https://www.amstat.org/asa/files/pdfs/P-ValueStatement.pdf'],
  multiple: ['FDA: Multiple Endpoints in Clinical Trials, October 2022', 'https://www.fda.gov/regulatory-information/search-fda-guidance-documents/multiple-endpoints-clinical-trials'],
  bh: ['Benjamini and Hochberg (1995): the false discovery rate procedure', 'https://doi.org/10.1111/j.2517-6161.1995.tb02031.x'],
  safety: ['ICH E2A: clinical safety definitions (FDA)', 'https://www.fda.gov/regulatory-information/search-fda-guidance-documents/e2a-clinical-safety-data-management-definitions-and-standards-expedited-reporting'],
  enrichment: ['FDA: Enrichment Strategies for Clinical Trials, March 2019 (PDF)', 'https://www.fda.gov/media/121320/download'],
  binomial: ['SciPy reference: binomial distribution', 'https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.binom.html'],
  bayes: ['FDA: Use of Bayesian Methodology in Clinical Trials of Drug and Biological Products, January 2026 draft', 'https://www.fda.gov/regulatory-information/search-fda-guidance-documents/use-bayesian-methodology-clinical-trials-drug-and-biological-products'],
  beta: ['SciPy reference: beta-binomial distribution', 'https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.betabinom.html'],
  missing: ['EMA: missing data in confirmatory clinical trials', 'https://www.ema.europa.eu/en/scientific-guidelines/missing-data-confirmatory-clinical-trials'],
  ni: ['FDA: Non-Inferiority Clinical Trials, November 2016', 'https://www.fda.gov/regulatory-information/search-fda-guidance-documents/non-inferiority-clinical-trials'],
  adaptive: ['FDA: Adaptive Design Clinical Trials for Drugs and Biologics, December 2019', 'https://www.fda.gov/regulatory-information/search-fda-guidance-documents/adaptive-design-clinical-trials-drugs-and-biologics-guidance-industry'],
};
const section = (id, title, body) => ({ id, title, body });
const table = (caption, headings, rows) => `<div class="table-scroll"><table><caption>${caption}</caption><thead><tr>${headings.map(h => `<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row => `<tr><th scope="row">${row[0]}</th>${row.slice(1).map(v => `<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const concepts = [
  {
    slug: 'trial-design', group: 'Start with the trial', title: 'Trial design, controls, and randomization',
    summary: 'Why the comparison group, randomization, blinding, and trial phase change what a result can establish.',
    intro: 'A drug result only makes sense in the design that produced it. Before reading a response rate or p-value, identify who entered the trial, what they received, and what the investigators compared.',
    sections: [
      section('design', 'What the design is trying to do', `<p>A <strong>single-arm trial</strong> gives everyone the study treatment. It can describe outcomes and identify activity, but an apparent improvement over historical experience may reflect differences in patients, care, or assessment. A <strong>randomized controlled trial</strong> assigns patients by chance to treatment strategies, making a causal comparison more credible when the trial is conducted and analyzed appropriately.</p><p>Randomization balances measured and unmeasured baseline characteristics in expectation, not perfectly in every sample. Allocation concealment prevents the upcoming assignment from influencing enrollment. Blinding reduces the influence of knowing treatment on care, reporting, or outcome assessment; it is different from concealment.</p>`),
      section('control', 'Choose the comparison that answers the question', `<p>A control can be placebo, active treatment, standard care, or standard care plus placebo. Placebo does not necessarily mean withholding effective therapy: both arms may receive a common standard treatment. An external control uses patients outside the randomized trial and needs a strong explanation of comparability.</p><div class="example"><h3>Example: an add-on treatment</h3><p>Compare standard care plus Drug A with the same standard care plus placebo. The contrast estimates the incremental effect of adding A under that treatment strategy. Comparing A in heavily pretreated patients with an older first-line study would answer a much less reliable question.</p></div>`),
      section('phases', 'Trial phases describe purpose', `<p>Phase 1 usually emphasizes dose, tolerability, and pharmacology; Phase 2 explores activity and refines the treatment strategy; Phase 3 usually tests confirmatory benefit and risk. Designs can overlap these purposes. A phase label alone does not establish the reliability of an endpoint, and a large uncontrolled study does not acquire randomization through its size.</p><p>Eligibility restrictions also affect generalizability. Results in a selected, healthier population may not transfer unchanged to patients with different disease severity, prior therapy, or organ function.</p>`),
      section('read', 'What to look for in a company readout', `<ul><li>Was assignment randomized, and was the ratio 1:1 or something else?</li><li>Did both arms receive comparable background care and follow-up?</li><li>Who was blinded, and were subjective endpoints independently assessed?</li><li>Were important baseline imbalances present?</li><li>Does the analysis preserve the planned comparison?</li></ul><p>Randomization supports the design; missing outcomes, treatment crossover, and selective reporting still need to be examined.</p>`),
    ], related: ['endpoints-and-estimands', 'missing-data'], sources: ['design', 'e9'],
  },
  {
    slug: 'endpoints-and-estimands', group: 'Start with the trial', title: 'Endpoints and estimands',
    summary: 'Define what was measured, in which patients, over what time, and how treatment changes were handled.',
    intro: 'An endpoint is the outcome being measured. An estimand is the precise treatment-effect question. A clear question comes before choosing the statistical test.',
    sections: [
      section('endpoint', 'An endpoint needs a definition and a clock', `<p>An endpoint specifies a measurement and how it is evaluated: response at a set visit, change in a symptom score by week 24, or time from randomization to an event. Primary endpoints address the main trial objective. Secondary endpoints add other planned information. Exploratory endpoints generate hypotheses.</p>${table('Common oncology endpoints', ['Endpoint', 'What it measures', 'Important distinction'], [
        ['Objective response rate (ORR)', 'Proportion with a protocol-defined complete or partial response', 'Tumor response does not by itself establish longer survival.'],
        ['Duration of response (DOR)', 'Time from response to progression or death, as defined in the protocol', 'Usually conditions on having responded; it describes a selected subset.'],
        ['Progression-free survival (PFS)', 'Time to progression or death', 'Scan schedule and progression assessment can influence results.'],
        ['Overall survival (OS)', 'Time to death from any cause', 'Follow-up, crossover, and subsequent therapy affect interpretation.'],
        ['Patient-reported outcome (PRO)', 'Symptoms, functioning, or quality of life reported by patients', 'The instrument, meaningful change, and missing reports matter.'],
      ])}`),
      section('estimand', 'Specify the treatment-effect question', `<p>Describe the population, treatment strategies, outcome, summary measure, and handling of <strong>intercurrent events</strong>: events after treatment starts that affect the outcome’s meaning or availability. Examples include stopping treatment, starting rescue medication, or death.</p><p>A treatment-policy question asks about outcomes under assignment to a strategy, including certain later treatment changes. A hypothetical question asks what might have happened under a specified alternative scenario, such as no rescue medication. These questions can need different data and assumptions. Death is not simply an ordinary missing symptom score.</p><p>Other strategies include a composite outcome that incorporates the event, a while-on-treatment question, or a principal-stratum question about a subgroup defined by potential events. They target different effects rather than interchangeable ways to improve a result.</p>`),
      section('example', 'One endpoint can answer different questions', `<div class="example"><h3>Example: a symptom trial</h3><p>A company measures symptom change at week 24. Some patients stop Drug A and receive rescue treatment. “What is the effect of assignment to A with rescue available?” differs from “What would A do if no one used rescue?” A treatment-policy analysis and a hypothetical analysis need not give the same answer.</p></div><p>The estimator is the procedure used to estimate the effect; the estimate is its numerical result. Neither should silently replace the question defined by the estimand.</p>`),
      section('surrogate', 'An earlier measurement may be a surrogate', `<p>A surrogate endpoint is used to stand in for a clinical outcome of interest in a particular setting. An association between a biomarker and prognosis does not by itself show that changing the biomarker with treatment changes clinical benefit. The strength of the relationship can depend on disease, therapy, and context.</p><p>Read the exact endpoint wording, data cutoff, treatment-change rules, and clinical interpretation together. A headline saying “met the endpoint” is incomplete without them.</p>`),
    ], related: ['trial-design', 'survival-analysis', 'missing-data'], sources: ['endpoints', 'estimand'],
  },
  {
    slug: 'data-and-variability', group: 'Start with the trial', title: 'Data types, averages, and variability',
    summary: 'Understand binary, continuous, and time-to-event data; distinguish standard deviation from standard error.',
    intro: 'The same word, “improvement,” can refer to a responder count, a change in a laboratory value, or a delay in disease progression. These are different kinds of data and need different summaries.',
    sections: [
      section('types', 'Match the summary to the data', `<p><strong>Binary data</strong> record outcomes such as response or no response. <strong>Continuous data</strong> measure quantities such as blood pressure or symptom score. <strong>Ordinal data</strong> have ordered categories whose distances need not be equal. <strong>Counts</strong> record numbers of events. <strong>Time-to-event data</strong> record how long until an event, often with incomplete follow-up.</p><p>A binomial model describes a fixed number of independent binary observations with a common probability. A normal model can approximate some continuous summaries. A Poisson model describes counts under restrictive rate assumptions; excess variability may call for another model. Choosing a distribution is an assumption to assess, not a property guaranteed by the endpoint’s name.</p>`),
      section('averages', 'Mean, median, and spread answer different questions', `<p>The <strong>mean</strong> is the sum divided by the number observed. The <strong>median</strong> is the middle value. A few extreme values can move the mean more than the median. The standard deviation (SD) describes variation among individual observations; the interquartile range describes the middle half.</p><div class="example"><h3>Example: uneven drug exposure</h3><p>Five exposure values are 1, 2, 2, 3, and 12 units. Their mean is 4, while the median is 2. Reporting only the mean hides the long upper tail. Neither summary establishes which exposure is effective or safe.</p></div><p>A percentage change, an absolute change, and a change from baseline adjusted for baseline covariates also answer different questions. Check the units and the analysis model.</p>`),
      section('se', 'Standard error measures uncertainty in an estimate', `<p>For independent observations with common finite variance, the estimated standard error of a sample mean is <strong>SE = SD / √n</strong>. It describes how much the estimated mean would vary across repeated samples. It does not describe how much individual patients vary.</p>${table('Same patient variability, different precision', ['Sample size', 'SD of individual outcomes', 'SE of the mean'], [['25', '10 units', '2 units'], ['100', '10 units', '1 unit']])}<p>Four times as many observations halves this SE under these assumptions. Correlated observations, such as repeated visits from the same patient, cannot simply be counted as independent patients.</p>`),
      section('models', 'Adjusted means and repeated measurements', `<p>Regression can estimate a treatment contrast while accounting for prespecified baseline variables. An adjusted mean is model-based and can differ from the raw average. A mixed model for repeated measures accounts for correlations across visits and requires assumptions about the outcome and missingness.</p><p>Ask whether error bars show SD, SE, or a confidence interval; whether the analysis uses individuals or repeated measurements; and whether the displayed summary matches the primary analysis. A narrow SE bar is not evidence that every patient had a similar outcome.</p>`),
    ], related: ['response-rates', 'confidence-intervals', 'effect-sizes'], sources: ['e9'],
  },
  {
    slug: 'response-rates', group: 'Start with the trial', title: 'Response rates and binomial probability',
    summary: 'Separate the observed proportion from the unknown probability, and inspect who enters the denominator.',
    intro: 'A response rate is a count divided by a denominator. The arithmetic is simple; the clinical definition, analysis population, and uncertainty determine what that number means.',
    sections: [
      section('proportion', 'Observed rate versus true probability', `<p>If x of n patients meet a response definition, the observed proportion is <strong>p̂ = x/n</strong>. The unknown response probability in a defined population is p. A sample proportion estimates p under a model; it does not reveal it exactly.</p><div class="example"><h3>Example: 18 responses</h3><p>Drug A produces 18 responses among 40 treated patients: 18/40 = 45%. If a report excludes ten patients without an evaluable scan and reports 18/30 = 60%, the higher rate comes from a different denominator. The exclusion might be prespecified, but its consequences still need explanation.</p></div><p>Confirmed and unconfirmed responses also differ. Confirmation rules, minimum response duration, assessor, and assessment schedule should be stated.</p>`),
      section('binomial', 'What a binomial model assumes', `<p>For n independent patients with the same response probability p, the responder count X follows a binomial distribution. Its expected value is np and its variance is np(1−p).</p><div class="formula">P(X = k) = C(n, k) p<sup>k</sup>(1−p)<sup>n−k</sup></div><p>C(n, k) counts the ways k responses can occur among n patients. The model allows random variation even when p stays fixed. It does not handle an unknown p merely by inserting a point estimate and calling it certain.</p>`),
      section('prediction', 'A count probability is a conditional calculation', `<div class="example"><h3>Example: ten future patients</h3><p>Assume p = 0.30 for ten independent patients. The expected count is 3, but P(X ≥ 4) is approximately 35.0%. An expected value is an average across repetitions, not a guarantee of three responses.</p></div><p>Changing p changes the distribution. Uncertainty about p can be modeled explicitly with a Bayesian predictive model; differences in future eligibility or care need additional assumptions. Neither a binomial tail probability nor an ORR is a probability of regulatory approval.</p>`),
      section('read', 'Questions before comparing two rates', `<ul><li>Are the response definitions, confirmation rules, and follow-up comparable?</li><li>Are all randomized patients, all treated patients, or only evaluable patients included?</li><li>Were missing outcomes excluded or handled through a prespecified rule?</li><li>Was the population chosen before looking at outcomes?</li><li>What is the confidence interval, and is the comparison randomized?</li></ul><p>A response rate in one arm describes that arm. Establishing an incremental treatment effect requires a defensible comparison.</p>`),
    ], related: ['confidence-intervals', 'bayesian-prediction', 'subgroups-and-bias'], sources: ['binomial', 'endpoints'],
  },
  {
    slug: 'confidence-intervals', group: 'Estimate the effect', title: 'Confidence intervals and the Wilson interval',
    summary: 'Read uncertainty around an effect estimate, and distinguish confidence, credible, and prediction intervals.',
    intro: 'A point estimate gives one number. An interval shows the precision of an estimation procedure under specified assumptions. It is useful to read the estimate and interval together.',
    sections: [
      section('meaning', 'What 95% confidence means', `<p>A 95% confidence procedure is designed to contain the fixed target parameter in about 95% of repeated samples when its assumptions hold. For the interval already calculated, frequentist confidence is not a posterior probability that the parameter lies inside it.</p><p>The interval describes uncertainty addressed by that procedure. It does not automatically account for biased sampling, a post hoc subgroup search, inaccurate measurements, or unreported analyses. More observations can narrow an interval around an estimate that still has bias.</p>`),
      section('wilson', 'Why use Wilson for a proportion?', `<p>The simple Wald interval p̂ ± 1.96√[p̂(1−p̂)/n] can behave poorly with small samples or proportions near 0 or 1. Wilson inverts a score test and keeps limits within the allowable probability range. Its coverage is approximate, not exact for every n and p.</p><p>With z = 1.96 for a two-sided 95% interval and d = 1 + z²/n:</p><div class="formula">center = [p̂ + z²/(2n)] / d<br>half-width = z √[p̂(1−p̂)/n + z²/(4n²)] / d<br>interval = center ± half-width</div><div class="example"><h3>Example: 12 of 20 patients respond</h3><p>The observed rate is 60%. The 95% Wilson interval is about 38.7%–78.1%. That wide range reflects the limited precision of twenty observations under a binomial model.</p></div><p>An exact binomial interval is another option and can be conservative. Bootstrap intervals resample observed data and need a resampling scheme appropriate for the design; they do not create information absent from the sample.</p>`),
      section('different', 'Three intervals, three targets', table('Do not interchange these intervals', ['Interval', 'Target', 'Interpretation depends on'], [
        ['Confidence interval', 'An unknown fixed population parameter', 'A repeated-sampling procedure and its assumptions'],
        ['Bayesian credible interval', 'A parameter with a posterior distribution', 'The prior, likelihood, and model'],
        ['Prediction interval', 'A future observation or count', 'Future variability and the chosen prediction model'],
      ]) + `<p>A Wilson interval does not supply a probability distribution for p. Using its endpoints as separate prediction scenarios is a sensitivity exercise, not a calibrated prediction interval.</p>`),
      section('comparison', 'Read intervals on the correct scale', `<p>No difference corresponds to 0 for a mean or risk difference, and 1 for a risk ratio, odds ratio, or hazard ratio. In compatible two-sided tests and intervals, excluding the null value corresponds to rejection at the matching significance level. Adjustments, methods, and prespecified thresholds must match.</p><p>Overlapping confidence intervals for two separate groups do not settle whether their difference is statistically significant. Estimate the contrast directly. Also ask whether the interval excludes effects too small to matter clinically, rather than only whether it excludes zero.</p>`),
    ], related: ['effect-sizes', 'p-values', 'bayesian-prediction'], sources: ['wilson', 'e9'],
  },
  {
    slug: 'effect-sizes', group: 'Estimate the effect', title: 'Effect sizes: absolute and relative benefit',
    summary: 'Compare risk differences, risk ratios, odds ratios, mean differences, and clinically meaningful effects.',
    intro: 'An effect size describes the magnitude of a difference or association. Its scale determines what a headline means. Statistical significance alone does not tell us how large or useful an effect is.',
    sections: [
      section('binary', 'Read absolute and relative measures together', `<div class="example"><h3>Example: a randomized response comparison</h3><p>At the same follow-up, 40/100 patients respond on Drug A and 25/100 respond on control. Assume comparable assessment and no missing outcomes for this illustration.</p></div>${table('Different summaries of the same hypothetical result', ['Measure', 'Calculation', 'Result'], [
        ['Risk difference', '0.40 − 0.25', '0.15, or 15 percentage points'],
        ['Risk ratio', '0.40 / 0.25', '1.60, or a 60% relative increase in response'],
        ['Odds ratio', '(0.40/0.60) / (0.25/0.75)', '2.00'],
        ['Number needed to treat for one additional response', '1 / 0.15', 'About 7, using this point estimate and follow-up'],
      ])}<p>An odds ratio of 2 does not mean the response probability doubled: the risk ratio here is 1.6. Odds and risks become closer when events are rare. Describe whether the event is beneficial or harmful before interpreting a ratio above or below 1.</p>`),
      section('precision', 'An observed benefit needs an uncertainty interval', `<p>For this example, a simple unadjusted large-sample interval for the risk difference is approximately 2.2–27.8 percentage points. This calculation is illustrative; score-based or other methods may be preferable depending on sample size and design.</p><div class="formula">SE(RD) ≈ √[p̂<sub>A</sub>(1−p̂<sub>A</sub>)/n<sub>A</sub> + p̂<sub>C</sub>(1−p̂<sub>C</sub>)/n<sub>C</sub>]</div><p>The point estimate of NNT hides this uncertainty and depends on baseline risk, outcome definition, and time horizon. If the risk-difference interval includes zero, the corresponding NNT uncertainty is especially awkward and should not be reduced to a single neat range.</p>`),
      section('continuous', 'Continuous outcomes need units', `<p>A mean difference of −5 mmHg is an absolute blood-pressure contrast. A standardized mean difference divides by a standard deviation and is unitless, which can help compare scales but is less directly clinical. A percent change depends on the baseline; it is not interchangeable with an absolute change.</p><p>A prespecified regression model may adjust for baseline measurements or other prognostic variables. Distinguish the adjusted treatment contrast from raw group means. Statistical adjustment cannot guarantee that two unrelated studies become comparable.</p>`),
      section('meaningful', 'Clinical importance is a separate question', `<p>A small effect can be precisely estimated in a very large trial. A potentially meaningful effect can be imprecise in a small trial. Judge the magnitude, interval, symptom or survival consequences, treatment burden, and safety together.</p><p>When reading a company release, identify the measure, direction, units, reference group, follow-up, and confidence interval. A relative percentage without the absolute outcomes omits information needed to judge its practical size.</p>`),
    ], related: ['confidence-intervals', 'survival-analysis', 'safety-and-benefit-risk'], sources: ['e9', 'asa'],
  },
  {
    slug: 'p-values', group: 'Estimate the effect', title: 'Hypothesis tests, p-values, and significance',
    summary: 'Understand the null hypothesis, Type I error, test choice, and why p < 0.05 does not establish clinical value.',
    intro: 'A hypothesis test assesses how compatible the observed data are with a specified statistical model. It is one part of evaluating evidence, alongside the design, effect size, uncertainty, and complete analysis plan.',
    sections: [
      section('null', 'Start with the null hypothesis', `<p>A null hypothesis might state that the two treatment strategies have the same mean outcome, or that a hazard ratio equals 1. An alternative specifies the departure being tested. A two-sided test considers effects in either direction; a one-sided test targets a direction specified in advance.</p><p>A p-value is the probability, under the null model and its assumptions, of a result at least as extreme as the observed result according to the chosen test. “Extreme” must be defined by that test. The number is not the probability that the null hypothesis is true.</p>`),
      section('example', 'Read a p-value without reversing the conditional', `<div class="example"><h3>Example: reported p = 0.03</h3><p>Under the specified null model, the test would produce results at least this extreme about 3% of the time. This does not mean there is a 3% chance the drug has no effect, a 97% chance it works, or a 97% chance it will be approved.</p></div><p>The interpretation also depends on whether the analysis was prespecified, whether all relevant tests were reported, and whether multiplicity or interim analyses changed the threshold.</p>`),
      section('alpha', 'Alpha is a property of the testing procedure', `<p>The significance level α limits the long-run probability of rejecting a true null hypothesis under the design’s assumptions. A prespecified α = 0.05 is not a 5% probability that any particular positive finding is false. That probability would require additional modeling and assumptions about the hypotheses being tested.</p><p>Type II error β is the probability of failing to reject under a specified alternative; power is 1−β. A nonsignificant result can reflect little effect, limited information, or both. It does not establish equivalence.</p>`),
      section('tests', 'Match the test to the endpoint and design', `<p>A t-test or regression contrast can compare continuous outcomes; chi-square or Fisher’s exact methods can compare binary outcomes; log-rank tests compare time-to-event distributions; model-based tests may account for prespecified covariates or repeated measures. Pairing, clustering, censoring, distributional assumptions, and sample size affect the choice.</p><p>The log-rank p-value and a Cox hazard ratio are related summaries but answer different questions. Under nonproportional hazards, a single hazard ratio may be difficult to interpret even when the test detects a difference.</p>`),
      section('read', 'Read beyond the threshold', `<p>p = 0.049 and p = 0.051 are close values. A sharp pass/fail boundary should not erase the effect estimate, interval, prespecified decision rule, or study limitations. A large p-value is not affirmative evidence that two therapies are equally effective.</p><p>Ask which null was tested, which analysis population was used, how the threshold was chosen, and whether the result was primary, multiplicity-adjusted, or exploratory.</p>`),
    ], related: ['effect-sizes', 'sample-size-and-power', 'multiple-testing'], sources: ['asa', 'e9'],
  },
  {
    slug: 'sample-size-and-power', group: 'Estimate the effect', title: 'Sample size, power, and detectable effects',
    summary: 'See how effect assumptions, variability, event counts, alpha, and dropout shape a trial’s ability to detect benefit.',
    intro: 'Power is the chance that a planned test rejects its null hypothesis when a specified alternative is true. It is a design calculation conditional on assumed effects and variability.',
    sections: [
      section('power', 'Power requires an alternative', `<p>A trial can have 80% power to detect a particular effect at a chosen α. That does not imply an 80% chance the treatment works or that the trial will succeed. If the real effect is smaller, the actual power is lower; if outcome variability is larger, the test also has less precision.</p><p>Inputs include the endpoint and analysis method, control outcome, target effect, allocation ratio, significance level, desired power, and expected missingness. Multiplicity, clustering, interim monitoring, and covariate adjustment can change the calculation.</p>`),
      section('example', 'An approximate two-arm example', `<div class="example"><h3>Example: 50% versus 30% response</h3><p>For independent equal-sized arms, a two-sided α = 0.05 and 80% power, a simple normal approximation gives about 93 evaluable patients per arm to detect a response difference of 20 percentage points. This is an illustration, not a proposed clinical design.</p></div><div class="formula">n per arm ≈ [z<sub>1−α/2</sub>√(2p̄(1−p̄)) + z<sub>1−β</sub>√(p<sub>A</sub>(1−p<sub>A</sub>) + p<sub>C</sub>(1−p<sub>C</sub>))]² / (p<sub>A</sub>−p<sub>C</sub>)²</div><p>Here p̄ is the average assumed response probability. Inflating 93 by 1/(1−0.10) gives about 104 enrolled per arm for 10% nonevaluability, after rounding. Enrollment inflation does not solve bias from missing outcomes.</p>`),
      section('information', 'Information is not always a patient count', `<p>For a survival endpoint, the number and timing of observed events often drive power more directly than enrollment alone. Accrual speed, follow-up, censoring, and the assumed hazard pattern determine how many events become available.</p><p>For an independent mean, SE decreases approximately as 1/√n. Halving SE therefore requires about four times the sample size, all else equal. Detecting a smaller effect can demand substantially more information.</p>`),
      section('assumptions', 'Optimistic design assumptions can mislead', `<p>Planning with an exaggerated effect from a small or selected early cohort can yield an underpowered later trial. Use realistic assumptions and examine a range of plausible effects and control outcomes. A target effect should be clinically meaningful, not merely convenient for making a trial smaller.</p><p>After observing a result, “observed power” calculated by plugging in the observed effect mostly repackages that result. The effect estimate and interval are more useful for understanding what the study learned.</p>`),
      section('read', 'Questions for a trial-size announcement', `<ul><li>Which effect and control outcome were assumed?</li><li>Is the target an enrolled-patient count or an event count?</li><li>What power and alpha were used, including multiplicity and interim looks?</li><li>How were missing data and follow-up modeled?</li><li>Was a re-estimation rule specified before examining treatment differences?</li></ul>`),
    ], related: ['p-values', 'survival-analysis', 'interim-and-adaptive'], sources: ['e9', 'adaptive'],
  },
  {
    slug: 'multiple-testing', group: 'Check what can mislead', title: 'Multiple testing and false discoveries',
    summary: 'Understand family-wise error, Bonferroni and Holm adjustments, testing hierarchies, and false discovery rate.',
    intro: 'Testing more endpoints, doses, subgroups, or analysis times creates more opportunities for a chance finding. A persuasive result needs an account of the full set of opportunities to claim success.',
    sections: [
      section('problem', 'Why many tests change the picture', `<p>If twenty independent tests all have true null hypotheses and each uses α = 0.05, the probability of at least one rejection is <strong>1 − 0.95²⁰ ≈ 64.2%</strong>. This is an illustrative independence calculation. Real endpoints are often correlated, so that exact number does not generally apply, but the multiplicity problem remains.</p><p>A testing family groups hypotheses for which a joint error criterion is controlled. Endpoint ordering, dose comparisons, subgroup tests, and interim looks can contribute to the testing strategy.</p>`),
      section('fwer', 'Control the chance of any false positive in a family', `<p><strong>Family-wise error rate (FWER)</strong> is the probability of at least one false rejection in the defined family. Bonferroni compares each of m p-values with α/m and controls FWER without requiring independence. With twenty tests and α = 0.05, the threshold is 0.0025 per test.</p><p><strong>Holm’s method</strong> orders p-values and uses successive thresholds α/m, α/(m−1), and so on, stopping when a comparison fails. It also controls FWER under general dependence and can reject more hypotheses than simple Bonferroni.</p><p>A prespecified fixed-sequence hierarchy can pass alpha through an ordered set of hypotheses. Its validity depends on following its rules; a favorable secondary endpoint does not automatically support a confirmatory claim after a failed gate.</p>`),
      section('fdr', 'FDR controls a different quantity', `<p><strong>False discovery rate (FDR)</strong> is the expected fraction of false rejections among all rejections, with fraction zero when none are rejected. The Benjamini–Hochberg procedure orders m p-values and finds the largest rank k satisfying p<sub>(k)</sub> ≤ (k/m)q, then rejects through that rank.</p><p>The usual guarantee applies under independence and certain positive-dependence conditions, not every dependency structure. FDR methods are useful in exploratory settings such as biomarker screens. They are not interchangeable with FWER control for confirmatory claims.</p><div class="example"><h3>Example: q = 0.05</h3><p>This controls an average false-discovery proportion under the method’s assumptions. It does not guarantee that exactly 5% of the discoveries in this dataset are false, or give each reported biomarker a 5% probability of being false.</p></div>`),
      section('read', 'Interpret the testing plan before the smallest p-value', `<p>Look for the prespecified family, primary endpoint structure, alpha allocation, interim monitoring, and any testing hierarchy. Distinguish adjusted p-values from nominal p-values. If multiple co-primary endpoints must all succeed, that design has a different error structure from claiming success if any one succeeds.</p><p>Unreported searches make a favorable result hard to evaluate. An exploratory finding can be valuable as a hypothesis while still needing prospective confirmation.</p>`),
    ], related: ['p-values', 'subgroups-and-bias', 'interim-and-adaptive'], sources: ['multiple', 'bh'],
  },
  {
    slug: 'subgroups-and-bias', group: 'Check what can mislead', title: 'Subgroups, enrichment, and selection bias',
    summary: 'Separate a biological hypothesis from a validated predictive biomarker, and understand post-selection optimism.',
    intro: 'A treatment may work differently across patients, but finding a high response rate in a subgroup is only the beginning. The definition, search process, comparison, and independent evidence determine how much to trust it.',
    sections: [
      section('selection', 'A correct description can be an optimistic forecast', `<p>The observed rate in a chosen subgroup can accurately describe those patients. Bias becomes a concern when a subgroup selected for looking good is used to estimate future performance without accounting for the selection process. Searching many biomarker cutoffs, combinations, or exclusions can favor an unusually positive result.</p><div class="example"><h3>Example: the best of eight groups</h3><p>Imagine eight small groups with identical true treatment-response probabilities. Random variation gives them different observed rates. Selecting the highest one after seeing outcomes makes the selected estimate optimistic on average. The exact bias depends on how the search was conducted.</p></div><p>A confidence interval calculated as though the selected subgroup were fixed in advance generally does not correct this selection.</p>`),
      section('biomarker', 'Prognostic is different from predictive', `<p>A <strong>prognostic</strong> biomarker is associated with outcomes regardless of which treatment is assigned. A <strong>predictive</strong> biomarker identifies differences in treatment effect. Better outcomes in biomarker-positive patients on a single treatment may reflect prognosis rather than a greater incremental benefit from that treatment.</p><p>A randomized treatment-by-biomarker interaction analysis can address effect modification on the specified scale. “Significant in subgroup A” and “not significant in subgroup B” is not itself a significant difference between subgroup effects.</p>`),
      section('enrichment', 'Enrichment changes who the evidence applies to', `<p>Enrichment deliberately selects patients to make a trial more informative, for example by reducing measurement variability, increasing baseline event risk, or targeting people more likely to benefit. A rule with biological rationale can improve a future design, but its performance should be evaluated prospectively.</p><p>Restricting eligibility also narrows the population to which the result directly applies. A stronger effect in a smaller selected population does not imply the same effect in all patients, or that the fraction meeting the criteria is known precisely.</p>`),
      section('other-bias', 'Other biases survive large samples', `<p>Confounding arises when treatment or group membership is associated with other causes of outcomes. Attrition can favor one treatment if missingness depends on outcomes. Measurement bias can enter through unblinded assessment. Publication and reporting bias can make the available evidence look more favorable than the full record.</p><p>Randomization, blinding, complete follow-up, prespecification, and transparent reporting address different problems; no one method fixes all of them.</p>`),
      section('validation', 'What would strengthen the finding?', `<ul><li>A subgroup rule and analysis plan fixed before new outcomes are examined.</li><li>A justified interaction analysis when claiming differential treatment effect.</li><li>Independent data with comparable treatment and assessment.</li><li>Reporting of the full subgroup search, uncertainty, and missing data.</li></ul><p>The <a href="iovance-data-first.html">Iovance case study</a> works through the distinction between an observed subgroup rate and a future prediction.</p>`),
    ], related: ['multiple-testing', 'trial-design', 'confidence-intervals'], sources: ['enrichment', 'e9'],
  },
  {
    slug: 'survival-analysis', group: 'Follow outcomes over time', title: 'Survival analysis, censoring, and hazard ratios',
    summary: 'Read Kaplan–Meier curves, median survival, hazard ratios, log-rank tests, and restricted mean survival time.',
    intro: 'Time-to-event analysis uses both whether an event occurred and when it occurred. It also handles patients whose event time is not fully observed, through explicit censoring assumptions.',
    sections: [
      section('censoring', 'What censoring says', `<p>For OS, a patient alive at the last known follow-up is right-censored: the event time is later than the observed follow-up time. Censoring is not an event and does not mean that the patient will never experience one. For other endpoints, such as PFS, the protocol defines both events and censoring rules.</p><p>Common methods require censoring to be noninformative under the relevant model or conditional assumptions. Losing patients because they are deteriorating can violate that assumption. Administrative censoring at a common data cutoff is different from unexplained loss to follow-up.</p>`),
      section('km', 'Kaplan–Meier updates survival at observed event times', `<p>At each event time, multiply the previous survival estimate by (1 − events / number at risk immediately before that time). Censoring reduces the later risk set without causing a downward step at the censoring time.</p>${table('A hypothetical five-patient example', ['Time', 'What happens', 'Estimated survival'], [['Month 2', '1 event among 5 at risk', '1 × (4/5) = 0.80'], ['Month 3', '1 patient censored', 'Remains 0.80; later risk set becomes 3'], ['Month 4', '1 event among 3 at risk', '0.80 × (2/3) ≈ 0.533']])}<p>Read the numbers at risk and confidence intervals under the curve. A dramatic late separation based on very few remaining patients is less precise than the line alone may suggest.</p>`),
      section('median', 'Median survival and landmark survival', `<p>The KM median is the first time the estimated survival curve reaches 50% or below. “Median not reached” means the estimate has not crossed that level by the analyzed follow-up; it does not establish an arbitrarily long survival benefit.</p><p>A landmark survival estimate, such as S(12 months), summarizes the curve at a prespecified time. It needs an uncertainty interval and adequate follow-up. Comparing medians alone ignores other parts of the distribution.</p>`),
      section('hazard', 'A hazard ratio is not a risk ratio', `<p>A hazard is an instantaneous event rate among those still event-free. Under a proportional-hazards model, HR = 0.70 represents a treatment hazard 30% lower relative to control over time. It does not mean 30% longer survival or that 30% fewer patients have an event at every time point.</p><p>If hazards cross or treatment effects change with time, a constant HR can be a poor summary. A Cox model estimate depends on the data and model; examine curves and proportional-hazards assumptions. A log-rank test assesses differences between survival distributions and has greatest efficiency under proportional-hazards alternatives.</p>`),
      section('rmst', 'Restricted mean survival time offers a time-scale summary', `<p>RMST is the area under the survival curve up to a chosen horizon τ. An RMST difference of two months through 24 months means two additional average event-free or survival months within that window, depending on the endpoint. It is not an unrestricted lifetime gain.</p><p>The endpoint, horizon, censoring rules, follow-up maturity, effect measure, and prespecified analysis should be read together.</p>`),
    ], related: ['endpoints-and-estimands', 'effect-sizes', 'missing-data'], sources: ['endpoints', 'e9'],
  },
  {
    slug: 'bayesian-prediction', group: 'Follow outcomes over time', title: 'Bayesian updating and future prediction',
    summary: 'Connect prior, likelihood, posterior, credible intervals, and beta-binomial predictions without treating assumptions as facts.',
    intro: 'Bayesian analysis represents uncertainty about unknown quantities with probability distributions. Updating is explicit about the data model and the information supplied before seeing the current data.',
    sections: [
      section('update', 'Prior × likelihood gives the posterior', `<p>The <strong>prior</strong> represents information or assumptions about a parameter before the current data. The <strong>likelihood</strong> describes how those data would arise at different parameter values. The <strong>posterior</strong> combines them and is normalized to integrate to one.</p><div class="formula">posterior(p | data) ∝ likelihood(data | p) × prior(p)</div><p>A 95% posterior credible interval contains 95% of the posterior probability under that model. Its meaning differs from the repeated-sampling interpretation of a confidence interval. Neither interval automatically represents uncertainty from an unmodeled selection process.</p>`),
      section('beta', 'A binary-response example', `<div class="example"><h3>Example: 12 responses among 20 patients</h3><p>Use a Beta(1,1) prior for p and an independent binomial likelihood. The posterior is Beta(13,9): add twelve responses to the first parameter and eight nonresponses to the second. The posterior mean is 13/22 ≈ 59.1%, compared with the observed proportion of 60%.</p></div><p>For a Beta(a,b) distribution, the mean is a/(a+b). Its concentration affects how strongly the prior influences updating. Calling a prior “weak” should be justified in the specific setting; a uniform prior on p is not uniform after every transformation.</p>`),
      section('predict', 'Prediction includes future sampling variability', `<p>To predict m future patients, average Binomial(m,p) predictions over the posterior for p. A beta posterior produces a beta-binomial predictive distribution.</p><div class="formula">P(X<sub>future</sub> = k | data) = ∫ P(X<sub>future</sub> = k | p) π(p | data) dp</div><p>For the example’s Beta(13,9) posterior and m = 30, the expected count is 30 × 13/22 ≈ 17.7 responders. A fixed-p binomial prediction at p̂ = 0.60 has expected count 18 and ignores uncertainty about p. Their predictive spreads differ even when their means are similar.</p><p>A predictive probability of meeting a future responder threshold is conditional on the endpoint, future population, prior, and model. It is not automatically a probability of trial success, regulatory approval, or a market return.</p>`),
      section('sensitivity', 'Check the prior and the data-generating assumptions', `<p>Repeat the analysis with defensible alternative priors and report what changes. External data need a comparability argument before they are borrowed: different eligibility, measurement, background care, or follow-up can make historical information misleading.</p><p>A model fit to a retrospectively selected subgroup will not remove selection optimism merely because it is Bayesian. Calibration studies or simulations should evaluate a planned decision rule’s behavior across relevant scenarios.</p>`),
      section('read', 'What to ask about a Bayesian result', `<ul><li>What is the prior, and where did its information come from?</li><li>What likelihood and population assumptions were made?</li><li>Is the reported probability about a parameter, a future outcome, or a decision rule?</li><li>How sensitive is it to the prior and historical borrowing?</li></ul><p>The linked FDA Bayesian document is a <strong>January 2026 draft</strong>, as checked on 31 October 2026; it is identified as a draft in the sources.</p>`),
    ], related: ['response-rates', 'confidence-intervals', 'interim-and-adaptive'], sources: ['bayes', 'beta'],
  },
  {
    slug: 'missing-data', group: 'Check what can mislead', title: 'Analysis populations, missing data, and sensitivity',
    summary: 'Understand intention-to-treat, evaluable populations, missingness assumptions, imputation, and tipping-point analyses.',
    intro: 'Who gets analyzed, and how absent outcomes are handled, can change a result. Missing data are a scientific problem about what was not observed, rather than simply an empty-cell problem.',
    sections: [
      section('populations', 'Keep the analysis population explicit', `<p>The intention-to-treat principle evaluates randomized patients according to their assigned group, preserving the planned comparison as far as possible. A full analysis set may implement that principle with defined exceptions. A modified intention-to-treat set needs an exact definition; its label alone does not establish which exclusions were made.</p><p>A per-protocol set excludes certain protocol deviations. An as-treated analysis follows treatment received. An evaluable population may exclude missing assessments. Such selections can break the comparability created by randomization, particularly when exclusions relate to prognosis or treatment response.</p>`),
      section('example', 'An exclusion can change the apparent rate', `<div class="example"><h3>Example: response assessments are missing</h3><p>Of 100 randomized patients, 40 have a documented response, 40 have a documented nonresponse, and 20 lack an assessment. The observed-assessment rate is 40/80 = 50%. Counting every missing assessment as nonresponse gives 40/100 = 40%.</p></div><p>Neither number reveals the missing patients’ unobserved outcomes. A nonresponse rule may be part of an endpoint or analysis, but is not automatically conservative for a treatment contrast if missingness differs between arms. The estimand and scientific assumptions must explain the choice.</p>`),
      section('mechanisms', 'Three missingness assumptions', `<p><strong>Missing completely at random (MCAR)</strong> means missingness does not depend on observed or unobserved study data. <strong>Missing at random (MAR)</strong> allows dependence on observed information but, conditional on that information, not on the missing values. <strong>Missing not at random (MNAR)</strong> allows dependence on the missing values even after conditioning on observed data.</p><p>MAR does not mean missingness is harmless or literally random in everyday language. Data alone usually cannot establish MAR versus MNAR, because the relevant values are unobserved. Reasons and timing of missingness are therefore important.</p>`),
      section('methods', 'Estimation needs assumptions; sensitivity challenges them', `<p>Multiple imputation draws plausible missing values under a model and combines analyses so that imputation uncertainty is included. A mixed model for repeated measures can use observed longitudinal outcomes under its model and missingness assumptions. Neither method guarantees unbiased estimates when those assumptions are wrong.</p><p>Last observation carried forward treats a previous value as the later missing value; it can impose unrealistic outcome trajectories and understate uncertainty. Sensitivity analyses vary plausible assumptions while addressing the same estimand. A tipping-point analysis asks how unfavorable the missing outcomes would need to be to change a conclusion.</p>`),
      section('read', 'Treatment changes are not all missing data', `<p>Stopping treatment, using rescue therapy, and death can affect which outcome is meaningful even when data are collected. They are intercurrent events handled within the estimand. Missingness refers to the absence of information needed to estimate that target.</p><p>Read the randomized count, analyzed count, reasons for exclusion, follow-up completeness by arm, outcome collection after discontinuation, primary assumptions, and sensitivity analyses together.</p>`),
    ], related: ['endpoints-and-estimands', 'trial-design', 'subgroups-and-bias'], sources: ['estimand', 'missing'],
  },
  {
    slug: 'noninferiority', group: 'Design and interpret the decision', title: 'Superiority, noninferiority, and equivalence',
    summary: 'Understand why a failed superiority test does not prove similarity, and how a justified margin changes the question.',
    intro: 'Some trials aim to show a treatment is better. Others ask whether it avoids losing more than a justified amount of efficacy, perhaps in exchange for another advantage. These need different hypotheses.',
    sections: [
      section('questions', 'Three distinct questions', `<p><strong>Superiority</strong> asks whether a treatment improves the endpoint relative to control. <strong>Noninferiority</strong> asks whether a possible loss is smaller than a prespecified margin. <strong>Equivalence</strong> asks whether the difference lies within both a lower and an upper margin.</p><p>Failure to show superiority is not evidence of equivalence or noninferiority. An imprecise trial can be compatible with substantial benefit and substantial harm at once.</p>`),
      section('example', 'A margin needs a direction and a scale', `<div class="example"><h3>Example: response-rate difference</h3><p>Let Δ = p<sub>new</sub> − p<sub>control</sub>, so higher is better. Suppose the justified noninferiority margin is −10 percentage points. An estimated difference of −2 points with a matching 95% interval of −7 to +3 clears that margin because the lower limit is above −10.</p><p>An interval of −13 to +3 would not clear it. Both intervals include zero, so neither establishes superiority using the corresponding two-sided interval criterion.</p></div><p>The numerical example illustrates a conventional one-sided 2.5% test matched to a two-sided 95% interval. The actual significance level, test, endpoint scale, and multiplicity plan must be prespecified.</p>`),
      section('margin', 'A margin is not a convenience setting', `<p>The margin needs clinical and statistical justification, including credible evidence about the active control’s effect and how much of that benefit must be preserved. A very wide margin can make noninferiority easier to claim while allowing a clinically important loss.</p><p><strong>Assay sensitivity</strong> is the ability of the trial to distinguish effective from ineffective treatment. If poor adherence, weak outcome ascertainment, or an unsuitable population makes both arms look similar, a noninferiority conclusion can be misleading. The assumption that the control retains its historical effect also matters.</p>`),
      section('analyses', 'Analysis populations and equivalence', `<p>Intention-to-treat and per-protocol analyses can be affected differently by nonadherence and exclusions. Neither should be assumed universally conservative in noninferiority trials; concordance and sensitivity need interpretation.</p><p>Equivalence requires both bounds to fall within justified margins, using the intervals and error levels matched to the testing procedure. Switching from a failed superiority test to an unplanned similarity claim changes the question after seeing the answer.</p>`),
      section('read', 'Read the advantage as well as the efficacy margin', `<p>A drug that is noninferior on one endpoint may still differ in safety, dosing burden, quality of life, or other outcomes. Those advantages need their own evidence and, where applicable, a multiplicity plan. Noninferiority is not a statement that the products are identical.</p>`),
    ], related: ['confidence-intervals', 'missing-data', 'effect-sizes'], sources: ['ni', 'e9'],
  },
  {
    slug: 'interim-and-adaptive', group: 'Design and interpret the decision', title: 'Interim analyses and adaptive designs',
    summary: 'Understand alpha spending, early stopping, futility, sample-size re-estimation, and planned adaptations.',
    intro: 'Learning during a trial can improve decisions, but repeatedly looking at accumulating results changes the statistical procedure. A valid design plans how interim information may affect the trial.',
    sections: [
      section('looks', 'Repeated significance testing creates extra opportunities', `<p>Testing at the usual final threshold after every look can increase false positives. The interim results are correlated, so treating those looks as independent tests is generally incorrect, but ignoring them is also incorrect.</p><p>A group-sequential design uses prespecified boundaries for interim and final analyses. An alpha-spending approach allocates the error budget across information times. Early efficacy boundaries are often more demanding than the final boundary, depending on the chosen design.</p>`),
      section('stopping', 'Efficacy, futility, and safety are different decisions', `<p>An efficacy rule stops for sufficiently strong evidence of benefit under the design. A futility rule stops when continued success appears unlikely according to a specified criterion. A safety stop responds to concerning risk and may not be based on the efficacy testing boundary.</p><div class="example"><h3>Example: three planned looks</h3><p>A trial plans analyses at 50%, 75%, and 100% of its target information. A nominal p = 0.03 at the first look might not cross its prespecified efficacy boundary, even though it is below 0.05. The actual boundaries come from the design, not this example.</p></div><p>Stopping for futility does not prove the treatment effect is exactly zero. A trial stopped early for a favorable effect can also have an upward-biased naive effect estimate; estimation and intervals should reflect the stopping design where appropriate.</p>`),
      section('adapt', 'Adaptation should be planned and evaluated', `<p>Adaptive designs can change features such as sample size, allocation, or which doses continue, according to prespecified rules using accumulating data. Blinded sample-size re-estimation based on nuisance quantities differs from changing sample size after seeing the treatment difference.</p><p>Choosing the best dose or population and then analyzing it as if no selection occurred can distort error rates and effect estimates. Simulations can evaluate operating characteristics across scenarios: false positives, power, bias, expected sample size, and stopping probabilities.</p>`),
      section('governance', 'Who sees the interim data matters', `<p>An independent data monitoring committee may review unblinded information under a defined charter. Preserving trial integrity limits the ways knowledge of interim results could influence enrollment, treatment, or assessment. A company’s public update does not necessarily describe all committee analyses.</p><p>Bayesian predictive probabilities can inform an adaptive decision rule, but the rule’s behavior still needs evaluation. “Bayesian” does not mean that repeated looks, selection, or operational bias disappear.</p>`),
      section('read', 'Questions for an interim announcement', `<ul><li>Was the look planned, and what fraction of information was available?</li><li>What boundary or predictive criterion applied?</li><li>Was stopping for benefit, futility, safety, or another reason?</li><li>Which adaptations were allowed, and who saw unblinded results?</li><li>Are reported estimates and intervals appropriate after selection or stopping?</li></ul>`),
    ], related: ['multiple-testing', 'sample-size-and-power', 'bayesian-prediction'], sources: ['adaptive', 'multiple'],
  },
  {
    slug: 'safety-and-benefit-risk', group: 'Design and interpret the decision', title: 'Safety statistics and benefit–risk',
    summary: 'Read adverse-event denominators, exposure time, uncertainty around rare events, and benefit alongside harm.',
    intro: 'Safety assessment asks which harms occurred, how often, how severe they were, and how they compare with expected outcomes without the treatment. A small study with few events provides limited information about uncommon risks.',
    sections: [
      section('events', 'Separate occurrence, severity, seriousness, and causality', `<p>An adverse event is an unfavorable occurrence during the study; its occurrence does not by itself establish that the drug caused it. A treatment-emergent event starts or worsens in the defined observation window. An investigator’s relatedness assessment is a separate judgment.</p><p><strong>Severe</strong> describes intensity. <strong>Serious</strong> refers to specified consequences such as death, a life-threatening event, or hospitalization; the terms are not interchangeable. Read the grading system, collection period, attribution rules, and event definitions.</p>`),
      section('denominators', 'Count people and account for exposure', `<div class="example"><h3>Example: ten affected patients</h3><p>If 10 of 100 patients experience at least one specified event, the patient incidence is 10%, even if those patients have 25 total episodes. A report of 25 events answers a different question from the number of affected patients.</p></div><p>Compare arms using consistent definitions and observation windows. Longer treatment or follow-up creates more opportunity to observe harm. An exposure-adjusted event rate, such as events per 100 person-years, accounts for time at risk but is not a probability. Recurrent events, time-varying risk, and competing events can make a simple rate insufficient.</p>`),
      section('zero', 'Zero observed events does not establish zero risk', `<p>Under an independent binomial model with complete comparable follow-up, the probability of observing zero events is (1−p)<sup>n</sup>. Setting this probability to 0.05 gives the one-sided 95% upper confidence bound:</p><div class="formula">p<sub>upper</sub> = 1 − 0.05<sup>1/n</sup> ≈ 3/n</div><div class="example"><h3>Example: no events among 100 patients</h3><p>The exact upper bound is about 2.95%; the “rule of three” approximation gives 3%. No events in this sample is therefore compatible with a risk near 3% under that model. It says nothing by itself about risks appearing after the study’s follow-up window.</p></div><p>This is a one-sided bound for one defined event, not a general certificate of safety.</p>`),
      section('comparison', 'Rare harms need context and further evidence', `<p>A safety comparison can be imprecise even when efficacy is well powered. Small samples, many event categories, incomplete follow-up, and selective eligibility all limit interpretation. A nominally significant imbalance deserves clinical evaluation, but a nonsignificant imbalance does not prove comparable safety.</p><p>Look for deaths, serious events, discontinuations, dose reductions, clinically important laboratory findings, and the reasons behind them. Broader exposure and longer observation can reveal risks absent in early development.</p>`),
      section('balance', 'Benefit–risk is more than a single score', `<p>Consider absolute benefit and absolute harm over relevant time horizons, their uncertainty, reversibility, severity, treatment burden, and available alternatives. Numbers needed to treat and harm can help only when endpoint definitions, comparable populations, follow-up, and uncertainty are clear.</p><p>A p-value or response probability alone cannot settle the clinical tradeoff. Different patient groups can reasonably value the same benefits and harms differently.</p>`),
    ], related: ['effect-sizes', 'confidence-intervals', 'trial-design'], sources: ['safety', 'wilson'],
  },
];

const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;');
const bySlug = new Map(concepts.map(c => [c.slug, c]));
const head = (title, description, prefix, interactive=false, dashboard=false) => `<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light dark">
<title>${escape(title)} · Kinley Tenzin</title>
<meta name="description" content="${escape(description)}">
<link rel="icon" href="data:,">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@500;600;700;800&amp;family=IBM+Plex+Mono:wght@400;500;600&amp;family=Source+Serif+4:opsz,wght@8..60,400;8..60,600&amp;display=swap" rel="stylesheet">
<link rel="stylesheet" href="${prefix}assets/research-notes.css?v=5">
${interactive?`<script type="module" src="${prefix}assets/statistics-labs.mjs?v=2"></script>`:''}
${dashboard?`<script type="module" src="${prefix}assets/statistics-dashboard.mjs?v=2"></script>`:''}
</head>`;
const nav = prefix => `<nav class="textnav" aria-label="Pages"><a href="${prefix}index.html">Home</a><a href="${prefix}statistics.html" aria-current="location">Alea</a><a href="${prefix}valuations.html">Investment theses</a><a href="${prefix}biotech.html">Biotech</a></nav>`;
const footer = prefix => `<footer><span>© 2026 Kinley Tenzin</span><a href="${prefix}statistics.html">Alea</a><a href="${prefix}valuations.html">Investment theses</a><a href="${prefix}biotech.html">Biotech</a></footer>`;

for (const concept of concepts) {
  for (const slug of concept.related) if (!bySlug.has(slug)) throw new Error(`Unknown related concept: ${slug}`);
  const html = `<!doctype html>
<html lang="en">
${head(concept.title, concept.summary, '../', true)}
<body>
<a class="skip" href="#main">Skip to explanation</a>
<div class="wrap">
${nav('../')}
<header class="guide-header">
<div class="dateline"><span>Alea · ${escape(concept.group)}</span><span>31 October 2026</span></div>
<p class="breadcrumb"><a href="../statistics.html">← All concepts in Alea</a></p>
<h1>${escape(concept.title)}</h1>
<p class="lede">${concept.intro}</p>
</header>
<main id="main" class="concept-body" tabindex="-1">
<p class="example-note">Numerical examples on this page are hypothetical unless a worked case study is explicitly linked.</p>
${renderLab(concept.slug)}
<article aria-label="${escape(concept.title)}">
${concept.sections.map(s => `<section id="${s.id}"><h2>${escape(s.title)}</h2>\n${s.body}</section>`).join('\n')}
<section id="related"><h2>Related concepts</h2><ul class="related-links">${concept.related.map(slug => `<li><a href="${slug}.html">${escape(bySlug.get(slug).title)}</a></li>`).join('')}</ul></section>
<section id="sources"><h2>Sources and further reading</h2><ul class="sources">${concept.sources.map(key => `<li><a href="${sources[key][1]}">${escape(sources[key][0])}</a></li>`).join('')}</ul><p class="muted">An educational explanation for reading drug-trial results. Interpretation of a particular study depends on its protocol, analysis plan, complete data, and clinical context.</p></section>
</article>
<p><a href="../statistics.html">← Back to Alea</a></p>
</main>
${footer('../')}
</div>
</body>
</html>
`;
  await writeFile(path.join(root, 'statistics', `${concept.slug}.html`), html, 'utf8');
}

const groups = ['Start with the trial', 'Estimate the effect', 'Check what can mislead', 'Follow outcomes over time', 'Design and interpret the decision'];
const folderSummaries = [
  'Design, endpoints, data, and response rates.',
  'Intervals, effect sizes, p-values, and power.',
  'Multiplicity, subgroup selection, and missing data.',
  'Survival curves and Bayesian prediction.',
  'Noninferiority, interim looks, and safety.',
];
const folders=groups.map((group,i)=>({id:`group-${i+1}`,name:group,summary:folderSummaries[i],concepts:concepts.filter(c=>c.group===group)}));
folders.push({id:'case-studies',name:'Company case studies',summary:'Apply the concepts to Iovance’s clinical data.',concepts:[{slug:'iovance-data-first',title:'Iovance: a data-first statistical roadmap',summary:'Work through the observations, subgroup selection, Wilson uncertainty, and conditional predictions.',caseStudy:true}]});
folders.push({id:'my-valuations',name:'Investment theses',summary:'What I think a company is worth, and why.',concepts:[{href:'valuations/iova.html',title:'$IOVA: why I get $5.83',summary:'Why I am cautious, how I think about melanoma and the lung data, and what would change my mind.',valuation:true}]});
const folderCount=folder=>`${folder.concepts.length} ${folder.id==='case-studies'?'case study':folder.id==='my-valuations'?'opinion case':'lessons'}`;
const lessonCard=(concept,folder)=>`<a class="lesson-card" data-lesson data-search="${escape(`${concept.title} ${concept.summary} ${folder.name}`)}" href="${concept.href||`statistics/${concept.slug}.html`}"><span class="lesson-kind">${concept.valuation?'Kinley Tenzin · Personal opinion':concept.caseStudy?'Worked company case':'Interactive lesson'}</span><h3>${escape(concept.title)}</h3><p>${escape(concept.summary)}</p><span class="lesson-open">${concept.valuation?'Read my case':concept.caseStudy?'Open case study':'Open lesson'} <span aria-hidden="true">↗</span></span></a>`;
const folderSection=folder=>{
  const headingId=folder.id==='case-studies'?'worked-case-title':`${folder.id}-title`;
  return `<section class="folder-section" id="${folder.id}" data-folder-section data-folder-name="${escape(folder.name)}" data-entry-kind="${folder.id==='my-valuations'?'opinion case':folder.id==='case-studies'?'case study':'lesson'}" aria-labelledby="${headingId}"><div class="folder-section-head"><h2 id="${headingId}" tabindex="-1">${escape(folder.name)}</h2><p>${escape(folder.summary)}</p></div><div class="lesson-grid">${folder.concepts.map(c=>lessonCard(c,folder)).join('\n')}</div>${folder.id==='case-studies'?'<p class="folder-note"><a href="notebooks/Iovance_Data_First_Companion.ipynb" download>Download the executed Iovance companion notebook (.ipynb)</a> · <a href="biotech.html">More biotech research</a></p>':''}</section>`;
};
const hub = `<!doctype html>
<html lang="en">
${head('Alea: evidence, statistics, and valuations', 'Browse interactive clinical-trial statistics, worked data cases, and Kinley Tenzin’s personal company valuations.', '', false, true)}
<body class="dashboard-page">
<a class="skip" href="#main">Skip to the learning folders</a>
<div class="wrap">
${nav('')}
<header class="guide-header">
<div class="dateline"><span>Kinley Tenzin · Alea</span><span>Evidence, uncertainty, and value</span></div>
<h1>Alea</h1>
<p class="lede">A visual library for reading drug-trial evidence and thinking about value. Open a learning folder, or explore my company valuations and the assumptions behind them.</p>
</header>
<main id="main" class="dashboard" data-learning-dashboard tabindex="-1">
<div class="library-toolbar"><div><h2 data-library-heading tabindex="-1">Explore the folders</h2><p class="library-count">16 interactive lessons · 1 data case · 1 personal valuation</p></div><div class="library-search" data-search-controls hidden><label for="lesson-search">Find a topic or company</label><div class="library-search-row"><input type="search" id="lesson-search" placeholder="Try Wilson, survival, or IOVA" autocomplete="off"><button type="button" data-clear-search hidden>Clear</button></div></div></div>
<nav class="folder-breadcrumb" aria-label="Folder path" data-folder-breadcrumb hidden><button type="button" data-all-folders>← All folders</button><span aria-hidden="true">/</span><span data-current-folder aria-current="page"></span></nav>
<p class="dashboard-status" data-dashboard-status role="status" aria-live="polite"></p>
<div class="folder-grid" data-folder-grid aria-label="Topic folders">
${folders.map((folder,i)=>`<a class="folder-card folder-tone-${i%3}" data-open-folder="${folder.id}" href="#${folder.id}"><span class="folder-tab" aria-hidden="true"></span><span class="folder-body"><span class="folder-meta"><span>${String(i+1).padStart(2,'0')}</span><span>${folderCount(folder)}</span></span><span class="folder-name">${escape(folder.name)}</span><span class="folder-summary">${escape(folder.summary)}</span><span class="folder-open">Open folder <span aria-hidden="true">→</span></span></span></a>`).join('\n')}
</div>
${folders.map(folderSection).join('\n')}
<section class="search-results" data-search-results aria-labelledby="search-results-title" hidden><h2 id="search-results-title">Search results</h2><div class="lesson-grid" data-search-grid></div><p data-no-results hidden>No entries match that search. Try a topic or company such as “response”, “power”, or “IOVA”.</p></section>
<noscript><p class="folder-note">The folders link to the lesson grids below. Every lesson is available without search.</p></noscript>
</main>
${footer('')}
</div>
</body>
</html>
`;
await writeFile(path.join(root, 'statistics.html'), hub, 'utf8');
// Update only the delimited exercise in the hand-written company article.
const iovancePath=path.join(root,'statistics','iovance-data-first.html');
let iovance=await readFile(iovancePath,'utf8');
const exercise=`<!-- statistics-lab:start -->\n${renderLab('iovance')}\n<!-- statistics-lab:end -->`;
if(iovance.includes('<!-- statistics-lab:start -->')) iovance=iovance.replace(/<!-- statistics-lab:start -->[\s\S]*?<!-- statistics-lab:end -->/,exercise);
else {
  const anchor=/<\/section>\r?\n\s*<section id="validation">/;
  if(!anchor.test(iovance))throw new Error('The Iovance prediction-section anchor is missing.');
  iovance=iovance.replace(anchor,`${exercise}\n    </section>\n    <section id="validation">`);
}
await writeFile(iovancePath,iovance,'utf8');
console.log(`Built the Statistics guide, ${concepts.length} interactive concept pages, and the Iovance exercise.`);
